<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$d=request_json();verify_csrf($d['_csrf']??'');$f=owned_file((int)($d['id']??0),$u['id']);db()->prepare('UPDATE files SET is_deleted=1,deleted_at=NOW(),updated_at=NOW() WHERE id=? AND user_id=?')->execute([$f['id'],$u['id']]);log_activity($u['id'],'Delete',$f['id'],$f['folder_id'],'Moved '.$f['file_name'].' to trash');json_response(['ok'=>1]);